请对以下 case 进行三维加权评分。

=== case_id ===
Case-23-countdown-006

=== 用户原始指令 (query.txt) ===
搞个生日倒计时,字在背景图上面,数字会动,点一下跳应用,读日历,已完成的也要显示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个生日倒计时,字在背景图上面,数字会动,点一下跳应用,读日历,已完成的也要显示",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "从本地日历读取的生日相关事件列表，第一条为待到来的生日倒计时，第二条为已完成纪念日。",
          "sampleValue": [
            {
              "entityName": "calendar",
              "entityId": "birthday-upcoming-001",
              "title": "妈妈生日",
              "description": "18",
              "dtStart": "7月27日 周一",
              "dtEnd": "7月27日 周一",
              "importantEventType": 2
            },
            {
              "entityName": "calendar",
              "entityId": "birthday-done-2025",
              "title": "去年生日",
              "description": "已过347天",
              "dtStart": "2025年7月27日",
              "dtEnd": "2025年7月27日",
              "importantEventType": 1
            }
          ],
          "items": {
            "type": "object",
            "description": "日历生日事件项。",
            "sampleValue": {
              "entityName": "calendar",
              "entityId": "birthday-upcoming-001",
              "title": "妈妈生日",
              "description": "18",
              "dtStart": "7月27日 周一",
              "dtEnd": "7月27日 周一",
              "importantEventType": 2
            },
            "properties": {
              "entityName": {
                "type": "string",
                "description": "内容类别，日历事件统一为 calendar。",
                "sampleValue": "calendar"
              },
              "entityId": {
                "type": "string",
                "description": "日历事件唯一标识符。",
                "sampleValue": "birthday-upcoming-001"
              },
              "title": {
                "type": "string",
                "description": "生日或纪念日日历事件标题。",
                "sampleValue": "妈妈生日"
              },
              "description": {
                "type": "string",
                "description": "日历事件描述中可用于展示的倒计时或已完成天数文本。",
                "sampleValue": "18"
              },
              "dtStart": {
                "type": "string",
                "description": "生日或纪念日开始日期展示文本。",
                "sampleValue": "7月27日 周一"
              },
              "dtEnd": {
                "type": "string",
                "description": "生日或纪念日结束日期展示文本。",
                "sampleValue": "7月27日 周一"
              },
              "importantEventType": {
                "type": "integer",
                "description": "重要日期类型，1 表示正数日，2 表示倒数日。",
                "sampleValue": 2
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule2.png",
      "description": "彩色日程 glyph，适合作为生日倒计时、日历纪念日和已完成日程的背景识别素材。"
    }
  ]
}

